'use strict';
// Synthetic replica of react-native-reanimated@3 sources: the published package
// points the "react-native" field at raw TypeScript that contains "worklet"
// directives and expects the Reanimated Babel plugin to compile them.
import { Platform } from 'react-native';

export const VIFX_SYNTHETIC_REANIMATED = 'VIFX_SYNTHETIC_REANIMATED_OK';

export interface SharedValue<Value> {
  value: Value;
}

export function makeMutable<Value>(initial: Value): SharedValue<Value> {
  'worklet';
  return { value: initial };
}

export function useSharedValue<Value>(initial: Value): SharedValue<Value> {
  return makeMutable(initial);
}

export function withTiming(toValue: number): number {
  'worklet';
  return toValue;
}

export function runOnUI<Args extends unknown[]>(worklet: (...args: Args) => void) {
  'worklet';
  return (...args: Args): void => {
    worklet(...args);
  };
}

export function getReanimatedPlatform(): string {
  return Platform.OS;
}

export default {
  makeMutable,
  runOnUI,
  useSharedValue,
  withTiming,
};
